// Shared by every page: helpers, translations, header and footer, language and theme.
// Each page script pushes its own redraw into onLang and calls applyLang() at the end.
const $=s=>document.querySelector(s);
const $$=(s,root=document)=>[...root.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const ico=(id,cls='')=>`<svg class="ico ${cls}" aria-hidden="true"><use href="#i-${id}"/></svg>`;
const fmt=(s,v)=>String(s).replace(/\{(\w+)\}/g,(_,k)=>v[k]??'');
// Private windows and blocked site data make localStorage throw; the page must still work.
const store={get:k=>{try{return localStorage.getItem(k)}catch(e){return null}},set:(k,v)=>{try{localStorage.setItem(k,v)}catch(e){}}};
