// 오류 신고와 문의. 결과 화면에서 열면 어느 지적이 잘못됐는지 골라서 보낼 수 있다.
const NOTE_HTML=`<div class="modal" id="note" role="dialog" aria-modal="true" aria-labelledby="noteT" hidden>
  <div class="modal-bg" data-noteclose></div>
  <div class="modal-card">
    <button class="modal-x" type="button" data-noteclose data-i18n-aria="close">${ico('x')}</button>
    <div class="g-body nform">
      <h2 id="noteT"></h2><p class="nlead" id="noteLead"></p>
      <label class="nf" id="noteSpotBox" hidden><span data-i18n="noteSpot"></span><select id="noteSpot"></select></label>
      <label class="nf"><span data-i18n="noteText"></span><textarea id="noteText" rows="5" maxlength="2000"></textarea></label>
      <label class="nf"><span data-i18n="noteContact"></span><input id="noteContact" type="text" maxlength="120" autocomplete="off"></label>
      <div class="nshot" id="noteShotBox" hidden><img id="noteShotImg" alt=""><span data-i18n="noteShotOn"></span></div>
      <label class="nf-check" id="noteShareBox" hidden><input type="checkbox" id="noteShare"><span><b data-i18n="noteShare"></b><small data-i18n="noteKeep"></small></span></label>
    </div>
    <div class="g-foot"><p class="nmsg" id="noteMsg" role="status" aria-live="polite"></p><button class="btn btn-primary btn-sm" id="noteSend" type="button" data-i18n="noteSend"></button></div>
  </div></div>`;
let noteJob='',noteShot='',noteBack=null;
function openNote(kind,job,spots,pick,shot){
  const el=$('#note');el.dataset.kind=kind==='report'?'report':'ask';noteJob=job||'';
  $('#noteT').textContent=t(el.dataset.kind==='report'?'noteReportT':'noteAskT');
  $('#noteLead').textContent=t(el.dataset.kind==='report'?'noteReportLead':'noteAskLead');
  const list=spots||[];
  $('#noteSpotBox').hidden=!list.length;
  $('#noteSpot').innerHTML=list.map(x=>`<option>${esc(x)}</option>`).join('');
  if(pick&&list.includes(pick))$('#noteSpot').value=pick;
  noteShot=shot||'';
  $('#noteShotBox').hidden=!noteShot;
  if(noteShot)$('#noteShotImg').src=noteShot;
  $('#noteShareBox').hidden=!noteJob;$('#noteShare').checked=false;
  $('#noteText').value='';$('#noteText').placeholder=t('notePh');
  $('#noteContact').value='';$('#noteContact').placeholder=t('noteContactPh');
  $('#noteMsg').textContent='';$('#noteSend').disabled=false;
  noteBack=document.activeElement;el.hidden=false;document.body.style.overflow='hidden';$('#noteText').focus();
}
function closeNote(){$('#note').hidden=true;document.body.style.overflow='';if(noteBack&&noteBack.focus)noteBack.focus()}
function sendNote(){
  const text=$('#noteText').value.trim(),msg=$('#noteMsg'),btn=$('#noteSend');
  if(text.length<5){msg.textContent=t('noteShort');$('#noteText').focus();return}
  btn.disabled=true;msg.textContent=t('noteSending');
  fetch('/api/feedback',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({
    kind:$('#note').dataset.kind,text,
    spot:$('#noteSpotBox').hidden?'':$('#noteSpot').value,
    contact:$('#noteContact').value.trim(),job:noteJob,share:$('#noteShare').checked,shot:noteShot})})
  .then(r=>{if(!r.ok)throw new Error('send');return r.json()})
  .then(()=>{msg.textContent=t('noteThanks');setTimeout(closeNote,1200)})
  .catch(()=>{msg.textContent=t('noteFail');btn.disabled=false});
}

function chrome(){
  document.body.insertAdjacentHTML('afterbegin',SPRITE+'<a class="skip" href="#main" data-i18n="skip"></a>');
  $('#siteNav').innerHTML=`<div class="wrap nav-in">
    <a class="brand" href="/" id="brand"><img src="/static/logo.png" alt=""><span>CADLens</span><small data-i18n="brandSub"></small></a>
    <nav class="nav-links" id="navLinks" aria-label="CADLens">
      <a href="/#how" data-nav data-i18n="navHow"></a><a href="/ks" data-i18n="navKs"></a><a href="/accuracy" data-i18n="navAcc"></a><a href="/#faq" data-nav data-i18n="navFaq"></a><button type="button" class="navnote" data-note="ask" data-i18n="noteAsk"></button>
      <div class="nav-lang">${LANGS}</div>
    </nav>
    <div class="nav-actions">
      ${PAGE==='home'?`<button class="hbtn" id="guideBtn" type="button" data-i18n-aria="guideOpen">${ico('help')}<span class="lbl" data-i18n="guideOpen"></span></button>`:''}
      <button class="hbtn" id="theme" type="button"><svg class="ico i-sun" aria-hidden="true"><use href="#i-sun"/></svg><svg class="ico i-moon" aria-hidden="true"><use href="#i-moon"/></svg></button>
      ${LANGS}
      <button class="hbtn menu-btn" id="menuBtn" type="button" aria-controls="navLinks" aria-expanded="false" data-i18n-aria="menu">${ico('menu')}</button>
    </div></div>`;
  $('#siteFoot').innerHTML=`<div class="wrap">
    <div class="foot-top">
      <div><a class="brand" href="/" id="brand2"><img src="/static/logo.png" alt=""><span>CADLens</span></a><p class="foot-tag" data-i18n="footTag"></p></div>
      <nav class="foot-links" aria-label="CADLens"><a href="/ks" data-i18n="navKs"></a><a href="/accuracy" data-i18n="navAcc"></a><a href="https://github.com/ritual1127/naverogq" target="_blank" rel="noopener">${ico('code')}<span data-i18n="footSource"></span></a><button type="button" data-note="ask">${ico('help')}<span data-i18n="noteAsk"></span></button><span>NAVER OGQ AI Competition</span></nav>
    </div>
    <div class="legal"><h3 data-i18n="lgTitle"></h3><div class="legal-grid">
      <div><b data-i18n="lgPrivK"></b><p data-i18n="lgPrivV"></p></div><div><b data-i18n="lgAiK"></b><p data-i18n="lgAiV"></p></div>
      <div><b data-i18n="lgCopyK"></b><p data-i18n="lgCopyV"></p></div><div><b data-i18n="lgMinorK"></b><p data-i18n="lgMinorV"></p></div>
    </div></div>
    <div class="foot-bottom"><span>© CADLens · MIT License</span><span id="stkCredit" data-i18n="stkCredit" hidden></span><a href="https://github.com/ritual1127/naverogq#개인정보-처리" target="_blank" rel="noopener" data-i18n="lgMore"></a></div></div>`;
  document.body.insertAdjacentHTML('beforeend',NOTE_HTML);
  $('#noteSend').onclick=sendNote;
  $$('#note [data-noteclose]').forEach(el=>el.onclick=closeNote);
  document.addEventListener('click',e=>{const b=e.target.closest('[data-note]');if(b)openNote(b.dataset.note)});
  document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#note').hidden)closeNote()});
  const here=location.pathname.replace(/\/+$/,'')||'/';
  $$('#navLinks a,.foot-links a').forEach(a=>{if(a.origin===location.origin&&!a.hash&&a.pathname===here)a.setAttribute('aria-current','page')});
  const menu=$('#menuBtn'),links=$('#navLinks');
  const setMenu=open=>{links.classList.toggle('open',open);menu.setAttribute('aria-expanded',String(open))};
  menu.onclick=()=>setMenu(!links.classList.contains('open'));
  links.addEventListener('click',e=>{if(e.target.closest('a'))setMenu(false)});
  document.addEventListener('click',e=>{if(!e.target.closest('.nav'))setMenu(false)});
  document.addEventListener('keydown',e=>{if(e.key==='Escape'&&links.classList.contains('open')){setMenu(false);menu.focus()}});
  document.addEventListener('click',e=>{const b=e.target.closest('button[data-lang]');if(!b||b.dataset.lang===lang)return;lang=b.dataset.lang;store.set('cadcheck.lang',lang);applyLang()});
  $('#theme').onclick=()=>{const th=document.documentElement.dataset.theme==='dark'?'light':'dark';store.set(THEME_KEY,th);applyTheme(th)};
}

function applyLang(){
  document.documentElement.lang=lang;
  $$('button[data-lang]').forEach(b=>{const on=b.dataset.lang===lang;b.classList.toggle('on',on);b.setAttribute('aria-pressed',String(on))});
  $$('[data-i18n]').forEach(el=>{const v=t(el.dataset.i18n);el.textContent=el.hasAttribute('data-fmt')?fmt(v,FMT):v});
  $$('[data-i18n-aria]').forEach(el=>el.setAttribute('aria-label',t(el.dataset.i18nAria)));
  applyTheme(document.documentElement.dataset.theme||currentTheme());
  onLang.forEach(f=>f());
}

const THEME_KEY='cadcheck.theme';
function currentTheme(){return store.get(THEME_KEY)||(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light')}
function applyTheme(th){  // not `t` — that name is the translation lookup
  document.documentElement.dataset.theme=th;
  const b=$('#theme'),label=t(th==='dark'?'themeLight':'themeDark');b.title=label;b.setAttribute('aria-label',label);
}
matchMedia('(prefers-color-scheme: dark)').addEventListener('change',e=>{if(!store.get(THEME_KEY))applyTheme(e.matches?'dark':'light')});

// Sections fade in once as they scroll into view.
function reveal(){
  if(!('IntersectionObserver' in window)){$$('.reveal').forEach(el=>el.classList.add('in'));return}
  const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in');io.unobserve(e.target)}}),{rootMargin:'0px 0px -6% 0px'});
  $$('.reveal:not(.in)').forEach(el=>io.observe(el));
}

chrome();
